-- Migration 116: official NPC appearance catalog plus strictly cross-matched coordinate evidence.
-- Only resource families 0 and 2 are runtime-enabled because each family has two exact observed 0x72 profiles.
CREATE TABLE IF NOT EXISTS `god2_game`.`npc_appearance_identities` (
    `appearance_identity_id` bigint NOT NULL,`client_build_id` varchar(64) NOT NULL,`client_entity_handle` int unsigned NOT NULL,
    `name_zh_tw` varchar(150) NOT NULL,`name_original` varchar(150) NOT NULL,`official_selector` int unsigned NOT NULL,
    `official_resource_type` tinyint unsigned NOT NULL,`official_resource_ordinal` tinyint unsigned NOT NULL,
    `source_row` int NOT NULL,`source_sha256` char(64) NOT NULL,`raw_fields_json` json NOT NULL,
    `identity_evidence_status` varchar(30) NOT NULL,`runtime_family_status` varchar(30) NOT NULL,`enabled` tinyint(1) NOT NULL DEFAULT 1,
    PRIMARY KEY (`appearance_identity_id`),UNIQUE KEY `ux_npc_appearance_handle` (`client_build_id`,`client_entity_handle`),
    KEY `ix_npc_appearance_name` (`name_zh_tw`),KEY `ix_npc_appearance_selector` (`official_resource_type`,`official_resource_ordinal`),
    CONSTRAINT `ck_npc_appearance_enabled` CHECK (`enabled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Official NPCAppearData identity catalog';

ON DUPLICATE KEY UPDATE `name_zh_tw`=VALUES(`name_zh_tw`),`name_original`=VALUES(`name_original`),`official_selector`=VALUES(`official_selector`),`official_resource_type`=VALUES(`official_resource_type`),`official_resource_ordinal`=VALUES(`official_resource_ordinal`),`source_row`=VALUES(`source_row`),`source_sha256`=VALUES(`source_sha256`),`raw_fields_json`=VALUES(`raw_fields_json`),`identity_evidence_status`=VALUES(`identity_evidence_status`),`runtime_family_status`=VALUES(`runtime_family_status`),`enabled`=VALUES(`enabled`);

CREATE TABLE IF NOT EXISTS `god2_game`.`npc_coordinate_evidence` (
    `coordinate_evidence_id` bigint NOT NULL,`client_build_id` varchar(64) NOT NULL,`client_entity_handle` int unsigned NOT NULL,
    `map_id` bigint NOT NULL,`position_x` int NOT NULL,`position_y` int NOT NULL,`source_kind` varchar(50) NOT NULL,
    `source_reference` varchar(512) NOT NULL,`source_sha256` char(64) NOT NULL,`evidence_status` varchar(30) NOT NULL,
    `runtime_enabled` tinyint(1) NOT NULL DEFAULT 0,PRIMARY KEY (`coordinate_evidence_id`),
    KEY `ix_npc_coordinate_handle` (`client_build_id`,`client_entity_handle`),KEY `ix_npc_coordinate_map` (`map_id`),
    CONSTRAINT `fk_npc_coordinate_appearance` FOREIGN KEY (`client_build_id`,`client_entity_handle`) REFERENCES `god2_game`.`npc_appearance_identities` (`client_build_id`,`client_entity_handle`),
    CONSTRAINT `fk_npc_coordinate_map` FOREIGN KEY (`map_id`) REFERENCES `god2_game`.`maps` (`map_id`),
    CONSTRAINT `ck_npc_coordinate_runtime` CHECK (`runtime_enabled`=0 OR `evidence_status` IN ('Verified','Derived'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cross-matched NPC coordinate evidence; Candidate rows remain disabled';

ON DUPLICATE KEY UPDATE `client_entity_handle`=VALUES(`client_entity_handle`),`map_id`=VALUES(`map_id`),`position_x`=VALUES(`position_x`),`position_y`=VALUES(`position_y`),`source_kind`=VALUES(`source_kind`),`source_reference`=VALUES(`source_reference`),`source_sha256`=VALUES(`source_sha256`),`evidence_status`=VALUES(`evidence_status`),`runtime_enabled`=VALUES(`runtime_enabled`);

ON DUPLICATE KEY UPDATE `name_zh_tw`=VALUES(`name_zh_tw`),`name_original`=VALUES(`name_original`),`resource_key`=VALUES(`resource_key`),`evidence_status`=VALUES(`evidence_status`),`enabled`=VALUES(`enabled`),`admin_note`=VALUES(`admin_note`);

ON DUPLICATE KEY UPDATE `npc_id`=VALUES(`npc_id`),`npc_name_cache`=VALUES(`npc_name_cache`),`map_id`=VALUES(`map_id`),`map_name_cache`=VALUES(`map_name_cache`),`position_x`=VALUES(`position_x`),`position_y`=VALUES(`position_y`),`direction`=VALUES(`direction`),`official_resource_type`=VALUES(`official_resource_type`),`official_resource_ordinal`=VALUES(`official_resource_ordinal`),`official_selector_high_bits`=VALUES(`official_selector_high_bits`),`official_direction_code`=VALUES(`official_direction_code`),`official_state_code`=VALUES(`official_state_code`),`wire_evidence_status`=VALUES(`wire_evidence_status`),`identity_evidence_status`=VALUES(`identity_evidence_status`),`coordinate_evidence_status`=VALUES(`coordinate_evidence_status`),`service_evidence_status`=VALUES(`service_evidence_status`),`application_message_sha256`=VALUES(`application_message_sha256`),`opaque_template_sha256`=VALUES(`opaque_template_sha256`),`enabled`=VALUES(`enabled`),`admin_note`=VALUES(`admin_note`);

